import{_ as a,b as o,c as r,I as s}from"./chunks/framework.C6cPs9Ia.js";const g=JSON.parse('{"title":"总力战与抽卡忏悔录：一个高中生的 BA 日常","description":"蔚蓝档案活动记录：总力战分数、抽卡玄学与养成规划","frontmatter":{"title":"总力战与抽卡忏悔录：一个高中生的 BA 日常","date":"2026-08-31T00:00:00.000Z","tags":["蔚蓝档案","游戏","日常"],"cover":"/LQY/images/cover-d.jpg","head":[["meta",{"name":"description","content":"蔚蓝档案活动记录：总力战分数、抽卡玄学与养成规划"}],["meta",{"name":"keywords","content":"蔚蓝档案, Blue Archive, 总力战, 抽卡"}]]},"headers":[],"relativePath":"posts/ba-diary.md","filePath":"posts/ba-diary.md"}'),e={name:"posts/ba-diary.md"};function i(l,t,d,n,c,p){return o(),r("div",null,[...t[0]||(t[0]=[s('<p>暑假尾声的蔚蓝档案生活记录：总力战打到了多少分、青辉石花在了哪里，以及一份不知道能不能坚持的养成规划。</p><hr><h2 id="暑假的最后一场总力战" tabindex="-1">暑假的最后一场总力战 <a class="header-anchor" href="#暑假的最后一场总力战" aria-label="Permalink to &quot;暑假的最后一场总力战&quot;">​</a></h2><p>这期总力战是<strong>比纳（Binah）装甲部</strong>，压力测试玩得很上头。作为一个设备一般、操作一般的普通学生，目标从一开始就很朴素：INSANE 难度拿到徽章就收手。</p><div class="info custom-block"><p class="custom-block-title">本期战绩</p><ul><li><strong>难度</strong>：INSANE</li><li><strong>分数</strong>：2,147 万（最后一刀极限压线）</li><li><strong>队伍</strong>：水星野 + 芹香 + 白子*战术形态 + 纱绫</li><li><strong>用时</strong>：两把，第一把暴击率不给面子直接烂尾</li></ul></div><p>最气的是第一把打到一半手机弹出&quot;电量不足 20%&quot;，慌乱之中技能轴全乱。<strong>老师的最大敌人不是学生，是电量。</strong></p><h2 id="抽卡记录-含泪" tabindex="-1">抽卡记录（含泪） <a class="header-anchor" href="#抽卡记录-含泪" aria-label="Permalink to &quot;抽卡记录（含泪）&quot;">​</a></h2><p>八月这两期卡池，本人的青辉石流向如下：</p><table tabindex="0"><thead><tr><th>卡池</th><th>目标</th><th>抽数</th><th>结果</th><th>心情</th></tr></thead><tbody><tr><td>上旬</td><td>★★★ 星野（水着）</td><td>120</td><td>出了</td><td>狂喜</td></tr><tr><td>下旬</td><td>★★★ 宇泽玲</td><td>200</td><td>沉船</td><td>麻了</td></tr></tbody></table><p>两个池子一共吃掉攒了一个多月的石头，外加一张十连券。宇泽玲池子最后是靠井（200 抽兑换）捞的——捞完第二天的总力战每日就给了 40 抽的石头，你说气不气。</p><div class="danger custom-block"><p class="custom-block-title">抽卡玄学总结</p><ol><li>抽卡前不要看抽卡视频，会被吸走运气</li><li>单抽救命是真是假无法证明，但穷学生愿意信</li><li>最重要的玄学：<strong>作业写完再抽</strong>，会莫名变欧（样本量 1，仅供参考）</li></ol></div><h2 id="养成规划" tabindex="-1">养成规划 <a class="header-anchor" href="#养成规划" aria-label="Permalink to &quot;养成规划&quot;">​</a></h2><p>接下来到年底的素材规划，写给未来的自己看：</p><ol><li><strong>优先级最高</strong>：把水着星野的 EX 技能拉到 5 级，总力战输出核心</li><li><strong>其次</strong>：攒神秘报告，留给下个月的限定</li><li><strong>顺带</strong>：普通关卡 B 部分推完（卡在 15-5，作业副本不出来）</li><li><strong>绝不碰</strong>：装饰品收集（上次为了一个头像框刷了一下午，血亏）</li></ol><details><summary>关于&quot;游戏和学习怎么平衡&quot;（班主任版答案）</summary><p>简单：周中只做日常，周末才碰活动。 周中实在手痒就打开游戏，看一眼日程板，看一眼石英不足的体力，然后默默关掉—— 这招叫<strong>望梅止渴</strong>，非常好用。</p></details><p>那么，暑假最后的疯狂结束了。9 月的排位战，我们分高下——如果月考没把本高中生送走的话。</p>',16)])])}const m=a(e,[["render",i]]);export{g as __pageData,m as default};
